using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Effects;
using ImageGuide;
namespace WinISOPilot.Desktop;
public sealed partial class PilotWindow
{
    Window Dialog(string title,UIElement child,double width=820,double height=580,Window? owner=null)
    {
        var dialog=new Window{Title=title,Owner=owner??this,Width=Math.Min(width,SystemParameters.WorkArea.Width-32),Height=Math.Min(height,SystemParameters.WorkArea.Height-32),ResizeMode=ResizeMode.CanMinimize,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=FontFamily,FontSize=15,Content=Scroll(new Border{Padding=new Thickness(22),Child=child})};dialog.Resources.MergedDictionaries.Add(Resources);dialog.SetResourceReference(BackgroundProperty,"PageBrush");dialog.SetResourceReference(ForegroundProperty,"TextBrush");return dialog;
    }
    Button DialogClose(Window dialog,string text,bool defaultAction=false){var button=ActionButton(text,()=>dialog.Close());button.IsDefault=defaultAction;button.IsCancel=true;return button;}
    void ShowText(string heading,string text,Window? owner=null){var panel=new StackPanel();panel.Children.Add(Text(heading,23));panel.Children.Add(TextBoxRead(text,390));var dialog=Dialog(heading,panel,880,570,owner);panel.Children.Add(DialogClose(dialog,"Close",true));dialog.ShowDialog();}
    void HelpDialog()=>ShowText("Help · "+WorkspaceNames[workspace],"Guided journey: choose one ISO, explicitly inspect it, choose and confirm an observed edition, optionally request its Retail preference, review, then explicitly create a new ISO. Your source stays protected.\n\nAdvanced workspaces are optional. Apps can read actual provisioning and request narrow app removals; Components offers supported cleanup after that inventory. These require administrator, compatible tools and install.wim. Other preview wishes never become executable build operations. 'Unknown' and 'not implemented' are incomplete evidence, not successful checks.\n\nPause and cancel wait for safe checkpoints. Native work and final source verification finish first. Cleanup keeps files by default and only deletes eligible tracked files after your choice. Undo restores selections; it never rewrites files or completed ISOs.\n\nCtrl+K opens local navigation search. F1 opens this help. Use Tab, Enter and Space to navigate controls. Explanations are available in Details expanders; no hover popups block interaction.\n\nCurrent capability: "+session.Capability(workspace,Engine.RestartRequired));
    void ResultDialog(){if(session.Result==null){SetStatus("No verified ISO result exists for these choices.");return;}ShowText("Created ISO result",System.Text.Json.JsonSerializer.Serialize(session.Result,Engine.Json));}
    ListBoxItem CreateSearchItem(SearchEntry entry){var label=new StackPanel();label.Children.Add(ListText(entry.Title,17));label.Children.Add(ListText(entry.Description));return new ListBoxItem{Content=label,Tag=entry};}
    void ResearchDialog(string initial="")
    {
        var panel=new StackPanel();panel.Children.Add(Text("Research references · not installed inventory",24));panel.Children.Add(Muted("These feature families explain possibilities and limitations. They are not extra executable choices, and their presence does not prove applicability to your image."));var query=new TextBox{Text=initial};AutomationProperties.SetName(query,"Filter research references");panel.Children.Add(query);var list=new ListBox{Height=330};var details=TextBoxRead("Choose a reference.",330);var count=Muted("");panel.Children.Add(count);panel.Children.Add(Split(list,details,.7));void Filter(){list.Items.Clear();var matches=CapabilityCatalog.Search(query.Text);foreach(var family in matches)list.Items.Add(new ListBoxItem{Content=ListText(family.Name),Tag=family});count.Text=matches.Count+" of "+CapabilityCatalog.Items.Count+" reference families. No image inventory is implied.";if(list.Items.Count>0)list.SelectedIndex=0;else details.Text="No reference families match. Try a broader word.";}list.SelectionChanged+=(_,_)=>{if(list.SelectedItem is ListBoxItem item&&item.Tag is CapabilityFamily family)details.Text=family.Name+"\n\nPurpose: "+family.Purpose+"\n\nPrerequisites: "+family.Prerequisites+"\n\nConsequences: "+family.Consequence+"\n\nImplementation: "+family.PrototypeStatus+"\n\nNative capability: "+family.NativeCapability+"\n\nEvidence URL (text only): "+family.Evidence;};query.TextChanged+=(_,_)=>Filter();Filter();var dialog=Dialog("WinISOPilot · Research references",panel,1000,650);panel.Children.Add(DialogClose(dialog,"Close references",true));dialog.ShowDialog();
    }
    void ChangesDialog()
    {
        var panel=new StackPanel();panel.Children.Add(Text("Your changes",25));panel.Children.Add(Muted("Edition: "+(session.Edition?.Name??"not selected")+". Edition is context, not a deletion target. Removing a choice never deletes files or changes Windows."));var list=new StackPanel();panel.Children.Add(list);var dialog=Dialog("Your changes — choices only",panel,850,620);
        void Populate(){list.Children.Clear();var rows=new List<(string Id,string Name,string Scope,string Explanation,int Workspace)>();if(session.PreferEdition)rows.Add(("media:edition","Retail edition preference","Actual media action","Writes a preference in the new copy only. All editions remain; no license is supplied.",9));foreach(string app in session.RemoveApps)rows.Add(("app:"+app,app,"Actual selected-edition action","Removes provisioning for new users. Only a private WIM copy changes.",2));if(session.CleanupComponents)rows.Add(("servicing:cleanup","Clean replaced Windows components","Actual selected-edition action","DISM StartComponentCleanup only; no ResetBase and no promised savings.",3));foreach(string id in session.Preview.Requested){var option=PreviewRecipe.Options.Single(x=>x.Id==id);rows.Add(("option:"+id,option.Name,"Preview only — not applied",option.Consequence,option.Group switch{"Hardware"=>1,"Apps"=>2,"Components"=>3,"Registry"=>4,_=>6}));}foreach(var service in session.Preview.Services)rows.Add(("service:"+service.Key,service.Key+": "+service.Value,"Preview only — not applied","Actual service state and dependencies are unknown.",5));if(session.Preview.Region!=PreviewRecipe.Regions[0])rows.Add(("region",session.Preview.Region,"Preview only — not applied","No regional configuration or answer file is applied.",7));if(rows.Count==0)list.Children.Add(Muted("No requested changes. You can create a supported media copy without preview wishes."));foreach(var row in rows){var contents=new StackPanel();contents.Children.Add(Muted(row.Explanation));var actions=Row();var remove=ActionButton("Remove choice",()=>{if(busy)return;session.Remove(row.Id);Render();Populate();});remove.IsEnabled=!busy;actions.Children.Add(remove);actions.Children.Add(ActionButton("Go to choice",()=>{dialog.Close();Navigate(row.Workspace);Dispatcher.BeginInvoke(()=>HighlightTarget(row.Id=="media:edition"?"prefer-edition":row.Id),System.Windows.Threading.DispatcherPriority.ContextIdle);}));contents.Children.Add(actions);list.Children.Add(Card(row.Name,contents,row.Scope));}}
        Populate();panel.Children.Add(DialogClose(dialog,"Close changes",true));dialog.ShowDialog();
    }
    void SearchDialog()
    {
        var panel=new StackPanel();panel.Children.Add(Text("Find a workspace or choice",24));panel.Children.Add(Muted("Local navigation only. Opening a result never starts work or changes a choice."));var query=new TextBox();AutomationProperties.SetName(query,"Search workspaces and choices");panel.Children.Add(query);var results=new ListBox{Height=330};panel.Children.Add(results);var hint=Muted("Type a word such as drivers, printing, account or cleanup.");panel.Children.Add(hint);var dialog=Dialog("Search · Ctrl+K",panel,850,590);void Open(){if(results.SelectedItem is not ListBoxItem item||item.Tag is not SearchEntry entry)return;dialog.Close();Navigate(entry.Workspace);Dispatcher.BeginInvoke(()=>{if(entry.Id.StartsWith("reference:",StringComparison.Ordinal))ResearchDialog(entry.Title);else HighlightTarget(entry.Id);},System.Windows.Threading.DispatcherPriority.ContextIdle);}
        var open=ActionButton("Open selected result",Open,true);open.IsEnabled=false;query.TextChanged+=(_,_)=>{results.Items.Clear();var matches=Session.Search(query.Text);foreach(var entry in matches)results.Items.Add(CreateSearchItem(entry));hint.Text=string.IsNullOrWhiteSpace(query.Text)?"Type to search.":matches.Count==0?"No results. Try a broader or different word.":matches.Count+" local navigation results.";open.IsEnabled=matches.Count>0;if(results.Items.Count>0)results.SelectedIndex=0;};query.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){e.Handled=true;Open();}if(e.Key==Key.Down&&results.Items.Count>0)results.Focus();};results.MouseDoubleClick+=(_,_)=>Open();results.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){e.Handled=true;Open();}};var actions=Row();actions.Children.Add(open);actions.Children.Add(DialogClose(dialog,"Close search"));panel.Children.Add(actions);dialog.ContentRendered+=(_,_)=>query.Focus();dialog.ShowDialog();
    }
    Button? jobPause,jobCancel;
    void ShowJob()
    {
        if(jobWindow!=null){jobWindow.Activate();return;}var panel=new StackPanel();panel.Children.Add(Text("Your job · measured activity",24));panel.Children.Add(Muted("This view uses the same Pause, Resume and Cancel controls as the main window. Closing this view does not cancel work."));liveJobText=Text(JobDescription(),18);panel.Children.Add(liveJobText);var evidence=TextBoxRead(fullStatus,230);panel.Children.Add(evidence);var dialog=Dialog("WinISOPilot · Job activity",panel,850,590);jobWindow=dialog;var actions=Row();jobPause=ActionButton("Pause / resume",PauseJob);jobCancel=ActionButton("Cancel safely",CancelJob);actions.Children.Add(jobPause);actions.Children.Add(jobCancel);actions.Children.Add(ActionButton("Read full evidence",()=>{evidence.Text=fullStatus+"\n\nRun folder: "+lastOutput;}));actions.Children.Add(DialogClose(dialog,"Close job view"));panel.Children.Add(actions);dialog.Closed+=(_,_)=>{jobWindow=null;liveJobText=null;jobPause=null;jobCancel=null;};UpdateChrome();dialog.Show();
    }
}
